head.script:
scwin.onpageload = function() {
	var titles = ["Green", "Blue", "yellow", "red"];
	for (var i = 0; i < 20; i++) {
		var option = {
			"title": titles[i % 4],
			"src": "/sample/common_link/windowContainer_windowTab_WESE-1069_(WSQ-5978)_sub.xml",
			"windowId": "window" + (i + 1),
			"frameMode": "wframe"
		};
		if (i % 4 == 0) {
			option.defaultWidth = "400";
			option.defaultHeight = "300";
		}
		windowContainer1.createWindow(option);
	}
};

scwin.setOffset = function() {
	window.init_offset = (document.getElementById('windowContainer1_nameLayer_mf_windowContainer1_subWindow17') || document.getElementById('mf_windowContainer1_nameLayer_mf_windowContainer1_subWindow17')).getBoundingClientRect().right;
};

scwin.checkVal = function() {
	const changed_offset = (document.getElementById('windowContainer1_nameLayer_mf_windowContainer1_subWindow17') || document.getElementById('mf_windowContainer1_nameLayer_mf_windowContainer1_subWindow17')).getBoundingClientRect().right;
	return window.init_offset != changed_offset;
};
